	if len(builtins) == 0 {
		t.Fatal("BuiltinPresetsForTest() returned empty golden table")
	}

	for _, b := range builtins {
		// Try to mutate the bitrate of a built-in.
		loaded, err := repo.GetByName(b.Name)
